#[test]
fn help_groups_pipeline_commands_and_utilities() {
    let mut root = ExposedCli::command();
    let help = root.render_long_help().to_string();
    assert!(
        help.lines()
            .any(|line| line.trim_start().starts_with("util "))
    );
    for (mut tree, expected, absent) in [
        (
            DataArgs::command(),
            &["declarations", "members"][..],
            &["latest", "copy-latest-raw", "uuid-v7"][..],
        ),
        (
            UtilArgs::command(),
            &["latest", "copy-latest-raw", "uuid-v7"][..],
            &["declarations", "members"][..],
        ),
    ] {
        let help = tree.render_long_help().to_string();
        for name in expected {
            assert!(
                help.lines()
                    .any(|line| line.trim_start().starts_with(&format!("{name} "))),
                "{help}"
            );
        }
        for name in absent {
            assert!(
                !help
                    .lines()
                    .any(|line| line.trim_start().starts_with(&format!("{name} "))),
                "{help}"
            );
        }
    }
}

#[test]
fn schema_helpers_and_library_runners_work_without_an_async_runtime() -> anyhow::Result<()> {
    use clap::Parser;
    use exposed::inbound::cli::{Commands, Response, run_cli, run_util};
    use std::{
        future::Future,
        task::{Context, Poll, Waker},
    };

    fn immediate(future: impl Future<Output = Response>) -> Response {
        let mut future = std::pin::pin!(future);
        match future
            .as_mut()
            .poll(&mut Context::from_waker(Waker::noop()))
        {
            Poll::Ready(response) => response,
            Poll::Pending => panic!("schema inspection must finish without an async runtime"),
        }
    }

    for command in [
        vec!["data", "declarations", "fetch"],
        vec!["data", "declarations", "clean"],
        vec!["data", "declarations", "resolve"],
        vec!["data", "declarations", "load"],
        vec!["data", "members", "fetch"],
        vec!["data", "members", "load"],
        vec!["util", "latest"],
        vec!["util", "copy-latest-raw"],
        vec!["util", "uuid-v7"],
    ] {
        let args =
            ExposedCli::try_parse_from(["exposed"].into_iter().chain(command).chain(["--schema"]))?;
        let (schema, response) = match args.command {
            Commands::Data(args) => (
                args.schema_response().expect("schema mode"),
                immediate(run_cli(args)),
            ),
            Commands::Util(args) => (
                args.schema_response().expect("schema mode"),
                immediate(run_util(args)),
            ),
            Commands::Server | Commands::Migrate(_) => unreachable!("test covers schema commands"),
        };
        let mut inspected = vec![];
        let mut executed = vec![];
        let mut errors = vec![];
        assert_eq!(
            schema.write_to(&mut inspected, &mut errors)?,
            std::process::ExitCode::SUCCESS
        );
        assert_eq!(
            response.write_to(&mut executed, &mut errors)?,
            std::process::ExitCode::SUCCESS
        );
        assert!(errors.is_empty());
        assert_eq!(inspected, executed);
        let document: serde_json::Value = serde_json::from_slice(&inspected)?;
        assert!(document["success"].is_object());
        assert!(document["failure"].is_object());
    }
    Ok(())
}
